package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import java.io.*;import java.util.*;import org.json.*;
/** SAF backup excludes Telegram credentials, login databases, native downloads and API keys. */
final class TvBackup {
 static final String[] STORES={"player","tv-library","tv-ui"};
 static void export(MainActivity a){try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Muthumol-TV-backup.json");a.startActivityForResult(i,602);}catch(Exception e){Ui.message(a,"Backup","A document provider is required.");}}
 static void restore(MainActivity a){try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),603);}catch(Exception e){Ui.message(a,"Restore","A document provider is required.");}}
 static boolean allowed(String key){String k=key.toLowerCase(Locale.ROOT);return key.length()<512&&!k.contains("apikey")&&!k.contains("token")&&!k.contains("password")&&!k.contains("secret")&&!k.contains("subtitleuri")&&!k.contains("subtitlepath");}
 static JSONObject encode(Object v)throws JSONException {return new JSONObject().put("type",v instanceof Long?"long":v instanceof Integer?"int":v instanceof Float?"float":v instanceof Boolean?"boolean":"string").put("value",v);}
 static void restoreValue(SharedPreferences.Editor e,String k,JSONObject entry){String t=entry.optString("type");Object v=entry.opt("value");boolean mustLong=k.startsWith("pos:")||k.startsWith("duration:")||k.startsWith("subdelay:")||k.startsWith("seen:");if(mustLong&&!t.equals("long"))return;if(k.equals("tvSpeed")&&!t.equals("float"))return;if(t.equals("long")&&v instanceof Number)e.putLong(k,((Number)v).longValue());else if(t.equals("int")&&v instanceof Number)e.putInt(k,((Number)v).intValue());else if(t.equals("float")&&v instanceof Number){float f=((Number)v).floatValue();if(Float.isFinite(f))e.putFloat(k,k.equals("tvSpeed")?Math.max(.25f,Math.min(4,f)):f);}else if(t.equals("boolean")&&v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(t.equals("string")&&v instanceof String&&((String)v).length()<1000000)e.putString(k,(String)v);}
 static void result(MainActivity a,int request,int result,Intent data){if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();if(request==602){new Thread(()->{try{JSONObject root=new JSONObject().put("format","muthumol-tv").put("version",2);for(String store:STORES){JSONObject values=new JSONObject();for(Map.Entry<String,?> e:a.getSharedPreferences(store,0).getAll().entrySet())if(allowed(e.getKey())&&(e.getValue() instanceof String||e.getValue() instanceof Number||e.getValue() instanceof Boolean))values.put(e.getKey(),encode(e.getValue()));root.put(store,values);}byte[] bytes=root.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>4*1024*1024)throw new IOException("Backup exceeds 4 MB");try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open output");out.write(bytes);}a.runOnUiThread(()->Ui.message(a,"Backup","Settings, collections and history saved. Telegram login is not included."));}catch(Exception e){a.runOnUiThread(()->Ui.message(a,"Backup failed",e.getMessage()));}},"TV backup").start();}else new Thread(()->{try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open backup");byte[] b=new byte[8192];int n;while((n=in.read(b))>=0){if(bytes.size()+n>4*1024*1024)throw new IOException("Backup is too large");bytes.write(b,0,n);}}JSONObject root=new JSONObject(bytes.toString("UTF-8"));if(!"muthumol-tv".equals(root.optString("format"))||root.optInt("version")!=2)throw new IOException("Unsupported backup format");a.runOnUiThread(()->Ui.dialog(a).setTitle("Restore settings and history?").setMessage("Matching settings and saved progress will be overwritten. Telegram login stays.").setPositiveButton("Restore",(d,w)->{for(String store:STORES){JSONObject v=root.optJSONObject(store);if(v==null)continue;SharedPreferences.Editor edit=a.getSharedPreferences(store,0).edit();Iterator<String> keys=v.keys();int count=0;while(keys.hasNext()&&count++<10000){String k=keys.next();if(!allowed(k))continue;Object entry=v.opt(k);if(entry instanceof JSONObject)restoreValue(edit,k,(JSONObject)entry);}edit.apply();}a.home();}).setNegativeButton("Cancel",null).show());}catch(Exception e){a.runOnUiThread(()->Ui.message(a,"Restore failed",e.getMessage()));}},"TV restore").start();}
}
